// wf-family-photos — R15 read side (2026-06-13). Lists the family-photo root
// and returns recent images as data URLs for the shared gallery. Bearer auth
// is enforced by the webhook headerAuth credential. Read-only.
// NOTE (v1): returns the stored (already-compressed) images directly; a
// dedicated thumbnail pass is a follow-up optimization (README).
const fs = require('fs');
const path = require('path');
const FAMILY_ROOT = '/data/family-photos';
const IMG = /\.(jpe?g|png|webp)$/i;

const q = ($input.first().json && $input.first().json.query) || {};
let limit = parseInt(q.limit, 10);
if (!Number.isFinite(limit) || limit < 1 || limit > 48) limit = 12;

let files = [];
try {
  files = fs.readdirSync(FAMILY_ROOT)
    .filter(function (f) { return IMG.test(f); })
    .map(function (f) { var p = path.join(FAMILY_ROOT, f); return { f: f, t: fs.statSync(p).mtimeMs, p: p }; })
    .sort(function (a, b) { return b.t - a.t; })
    .slice(0, limit);
} catch (e) {
  return [{ json: { photos: [] } }];
}

const ext2mime = { '.jpg': 'jpeg', '.jpeg': 'jpeg', '.png': 'png', '.webp': 'webp' };
const photos = files.map(function (x) {
  var mime = ext2mime[path.extname(x.f).toLowerCase()] || 'jpeg';
  var b64 = fs.readFileSync(x.p).toString('base64');
  return { id: x.f, thumb: 'data:image/' + mime + ';base64,' + b64, date: new Date(x.t).toISOString().slice(0, 10), text: '' };
});
return [{ json: { photos: photos } }];
